window.AUTH=window.AUTH||{};window.AUTH["25-1017"]={"d":"25-1017","id":"2026/25-1017","n":"Republican National Committee v. Mi Familia Vota","briefs":[{"k":"petitioner","label":"Brief of petitioner Republican National Committee","date":"2026-08-28","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/422368/20260828134131686_26.08.28%20RNC%20v.%20MFV%20-%20Blue%20Brief%20DRAFT%20print%20ready.pdf","side":"pet","n":73},{"k":"respondent","label":"Brief of respondent United States in support of petitioner","date":"2026-08-28","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/422369/20260828134830716_25-1017tsUnitedStates.pdf","side":"res","n":77},{"k":"respondent","label":"Brief of respondents Warren Petersen, President of the Arizona Senate, et al. in support of petitioner","date":"2026-08-28","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/422435/20260828234248023_Brief_of_Petersen_and_Montenegro.pdf","side":"res","n":46},{"k":"respondent","label":"Brief of respondents Arizona, et al. in partial support of petitioner","date":"2026-08-28","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/422337/20260828104027296_25-1017%20Brief%20for%20Respondents%20State%20of%20Arizona%20and%20Attorney%20General.pdf","side":"res","n":25},{"k":"respondent","label":"Brief of respondents Democratic National Committee, et al.","date":"2026-10-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/429342/20261013151019052_25-1017%20bs%20DNC%20and%20Arizona%20Democratic%20Party.pdf","side":"res","n":27},{"k":"respondent","label":"Brief of respondents AZ AANHPI for Equity, et al.","date":"2026-10-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/429355/20261013154635354_25-1017_Respondents%20Brief.pdf","side":"res","n":97},{"k":"respondent","label":"Brief of respondents Mi Familia Vota, et al.","date":"2026-10-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-1017/429340/20261013150606871_25-1017%20Mi%20Familia%20Vota%20Merits%20Brief.pdf","side":"res","n":75}],"opinion":null,"tr":false,"items":[{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"0":"35","1":"25, 28","3":"23","5":"11-13"}},{"t":"case","label":"Arizona v. Inter Tribal Council of Ariz.","cite":"570 U.S. 1","y":2013,"id":"2012/12-71","sc":1,"sum":"The Court found the National Voter Registration Act preempted other voter registration requirements.","sumSrc":"Oyez","by":{"0":"1, 2, 5, 6, 13-17, 24, 29, 32, 33, 38","1":"3, 5, 7, 9, 15-21, 23, 24, 26, 28, 43","2":"2–3, 8–13, 21","3":"2, 3, 13, 14 ,15, 16, 18, 19, 20","4":"42","5":"3, 22, 25, 29-30, 48","6":"1, 3–5, 13, 19–21, 23, 26, 41"}},{"t":"case","label":"Ayestas v. Davis","cite":"584 U.S. 28","y":2018,"id":"2017/16-6795","sc":1,"sum":"The Court decided that the district court's denial of petitioner's request for \"reasonably necessary\" investigative and related services under 18 U.S.C. § 3599(f) to prove that he was entitled to federal habeas relief was a judicial decision subject to appellate review under the standard jurisdictional provisions; and that the U.S. Court of Appeals for the 5th Circuit applied the wrong legal standard in affirming the district court's denial of petitioner's § 3599(f) request.","sumSrc":"Oyez","by":{"0":"19, 26","1":"16, 19, 20","2":"12","3":"16","5":"26","6":"16"}},{"t":"case","label":"Bell v. Marinko","cite":"367 F.3d 588","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/367/588/","by":{"0":"51, 52","1":"42","4":"34, 39","5":"47, 49"}},{"t":"case","label":"Carrington v. Rash","cite":"380 U.S. 89","y":1965,"id":"1964/82","sc":1,"sum":"A State can impose reasonable residence requirements for voting but it cannot, under the Equal Protection Clause, deny the ballot to a bona fide resident merely because he is a member of the armed services. Pp. 89-97. 378 S. W. 2d 304, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Carson v. Simon","cite":"978 F.3d 1051","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/978/1051/","sum":"Holding that “the Secretary has no power to override the [State] Legislature” through a consent decree.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"Castañon-Nava v. DHS","cite":"175 F.4th 828","y":2026,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/175/828/","by":{"0":"34"}},{"t":"case","label":"Cellular Telecomms. & Internet Ass’n v. FCC","cite":"330 F.3d 502","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/330/502/","sum":"Deciding whether certain telecommunications regulations are “necessary to ensure” reasonable rates.","sumSrc":"brief:0","by":{"0":"22","1":"17, 20","5":"27"}},{"t":"case","label":"Crawford v. Marion Cnty. Election Bd.","cite":"553 U.S. 181","y":2008,"id":"2007/07-21","sc":1,"sum":"By a vote of 6 to 3, the Court upheld the law, concluding that the photo I.D. requirement was closely related to Indiana's legitimate state interests in preventing voter fraud.","sumSrc":"Oyez","by":{"0":"32","1":"19, 27"}},{"t":"case","label":"Crocker v. Spencer","cite":"2 D. Chip. 68","y":1824,"court":"Vt.","url":"https://www.courtlistener.com/c/D.%20Chip./2/68/","by":{"0":"20"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"597 U.S. 215","y":2022,"id":"2021/19-1392","sc":1,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"31","2":"15"}},{"t":"case","label":"Fish v. Kobach","cite":"840 F.3d 710","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/840/710/","sum":"Finding Kansas’s “meager evidence” failed to show any necessity for DPOC.","sumSrc":"brief:5","by":{"0":"25","1":"19","2":"12","5":"24, 29","6":"25"}},{"t":"case","label":"Foley v. Connelie","cite":"435 U.S. 291","y":1978,"id":"1977/76-839","sc":1,"sum":"In a 6-to-3 decision, the Court held that the states had an \"historical power to exclude aliens from participation in its democratic political institutions\" and that the New York statute did not violate the Equal Protection Clause.","sumSrc":"Oyez","by":{"0":"1"}},{"t":"case","label":"Foster v. Love","cite":"522 U.S. 67","y":1997,"id":"1997/96-670","sc":1,"sum":"The Court held that when Louisiana's open primary is applied to select among congressional candidates in October, it conflicts with federal law and to that extent is void. The Court rejected the argument that Louisiana's system only concerns the manner, not the time, of a federal election.","sumSrc":"Oyez","by":{"0":"4","1":"5"}},{"t":"case","label":"Frew v. Hawkins","cite":"540 U.S. 431","y":2004,"id":"2003/02-628","sc":1,"sum":"The Court held that enforcement of the consent decree does not violate the 11th Amendment.","sumSrc":"Oyez","by":{"0":"34, 36, 38, 40","1":"25, 28-30","2":"21","3":"22, 23","5":"13-15, 18","6":"37"}},{"t":"case","label":"FTC v. Rockefeller","cite":"591 F.2d 182","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/591/182/","sum":"Rejecting the “notion that ‘necessary’ means that the Commission must pursue all other ‘reasonably available alternatives’”.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Horne v. Flores","cite":"557 U.S. 433","y":2009,"id":"2008/08-289","sc":1,"sum":"The Court found that the lower court incorrectly analyzed Rule 60(b)(5), which allows a party to seek relief from a judgment if a significant change in the law has occurred.","sumSrc":"Oyez","by":{"0":"16, 33, 34, 36, 38","1":"25-28","2":"9, 21–22","3":"23, 26","5":"11-13, 18-19","6":"33, 36, 37"}},{"t":"case","label":"Hoult v. Hoult","cite":"157 F.3d 29","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/157/29/","by":{"0":"22"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"30","6":"3, 43, 44"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"League of Residential Neighborhood Advocs. v. City of L.A.","cite":"498 F.3d 1052","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/498/1052/","by":{"0":"36, 37"}},{"t":"case","label":"League of Women Voters of U.S. v. Newby","cite":"838 F.3d 1","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/838/1/","sum":"Holding that the EAC “determines necessity” for the federal form.","sumSrc":"brief:0","by":{"0":"24, 30","6":"23"}},{"t":"case","label":"Mamma Mia’s Trattoria v. Original Brooklyn Water Bagel Co.","cite":"768 F.3d 1320","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/1320/","by":{"0":"40, 41"}},{"t":"case","label":"Martin v. United States","cite":"605 U.S. 395","y":2025,"id":"2024/24-362","sc":1,"sum":"The Supremacy Clause does not afford the United States a defense in a suit against it under the Federal Tort Claims Act, 28 U. S. C. §2671 et seq., and the law enforcement proviso in §2680(h) of the FTCA overrides only the intentional-tort exception in that subsection, not the discretionary-function exception or other exceptions throughout §2680.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"50"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"2, 15, 20, 21, 25, 26","2":"12","5":"27"}},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"sum":"The Court held that Congress clearly intended to make operation of the PLRA's automatic stay provision mandatory, precluding courts from exercising their equitable power to enjoin the stay and that the PLRA does not violate separation of powers principles.","sumSrc":"Oyez","by":{"0":"40","1":"29","2":"18","5":"18","6":"38"}},{"t":"case","label":"Moore v. Harper","cite":"600 U.S. 1","y":2023,"id":"2022/21-1271","sc":1,"sum":"The Federal Elections Clause does not vest exclusive and independent authority in state legislatures to set the rules regarding federal elections and therefore did not bar the North Carolina Supreme Court from reviewing the North Carolina Legislature’s congressional districting plans for compliance with North Carolina law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38","2":"21","5":"17"}},{"t":"case","label":"NRDC v. Thomas","cite":"838 F.2d 1224","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/838/1224/","by":{"0":"26"}},{"t":"case","label":"Pigford v. Veneman","cite":"292 F.3d 918","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/292/918/","by":{"0":"39"}},{"t":"case","label":"Regions Bank v. Legal Outsource PA","cite":"936 F.3d 1184","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/936/1184/","by":{"0":"49"}},{"t":"case","label":"Rufo v. Inmates of Suffolk Cnty. Jail","cite":"502 U.S. 367","y":1992,"id":"1991/90-954","sc":1,"sum":"The Court held that the court does not require a grievous wrong evoked by new and unforeseen change of facts in order to modify a consented decree.","sumSrc":"Oyez","by":{"0":"34-37","1":"25, 26, 28","2":"18, 20","3":"21, 22","5":"10-12","6":"31, 34"}},{"t":"case","label":"Salazar v. Buono","cite":"559 U.S. 700","y":2010,"id":"2009/08-472","sc":1,"sum":"The Court held that an individual has standing to maintain a suit when he acquires a \"judicially cognizable\" interest in ensuring compliance with a previous judgment in his favor. The Court also held that a court may not order an injunction in a case when it fails to consider all the circumstances bearing on the need for preventive relief.","sumSrc":"Oyez","by":{"0":"34, 35","1":"29"}},{"t":"case","label":"Sys. Fed’n No. 91 v. Wright","cite":"364 U.S. 642","y":1961,"id":"1960/48","sc":1,"sum":"It erred in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 36, 40","2":"18","3":"22"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"sum":"Because universal injunctions likely exceed the equitable authority that Congress has granted to federal courts, the Court grants the Government’s applications for a partial stay of the injunctions entered below regarding the implementation and enforcement of President Trump’s Executive Order No. 14160, but only to the extent that the injunctions are broader than necessary to provide complete relief to each plaintiff with standing to sue.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"United States v. Swift & Co.","cite":"286 U.S. 106","y":1932,"id":"scdb/1931-111","sc":1,"sum":"(For opinion below see U. S. Daily, Jan. 6, 1931.)","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35","3":"22"}},{"t":"case","label":"United States v. Westinghouse Elec. Corp.","cite":"788 F.2d 164","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/788/164/","sum":"Interpreting the “Inspector General’s determination of what information is ‘necessary to carry out the functions assigned by this Act’”.","sumSrc":"brief:0","by":{"0":"22","5":"26"}},{"t":"case","label":"Young v. Fordice","cite":"520 U.S. 273","y":1997,"id":"1996/95-2031","sc":1,"sum":"The unanimous Court reversed the District Court and ruled that Mississippi must submit the New System to the Attorney General for pre-clearance. The opinion by Justice Stephen Breyer held that \"the New System contains numerous examples of new, significantly different administrative practices [....]\" Therefore, the Attorney General must ensure that the proposed policy does not discriminate against minorities.","sumSrc":"Oyez","by":{"0":"27","1":"5","3":"2","5":"3"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"usc","label":"10 U.S.C. § 8677","url":"https://www.law.cornell.edu/uscode/text/10/8677","by":{"0":"28"}},{"t":"usc","label":"12 U.S.C. § 2404","url":"https://www.law.cornell.edu/uscode/text/12/2404","by":{"0":"21"}},{"t":"usc","label":"12 U.S.C. § 5233","url":"https://www.law.cornell.edu/uscode/text/12/5233","by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 4806","url":"https://www.law.cornell.edu/uscode/text/15/4806","by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 8515","url":"https://www.law.cornell.edu/uscode/text/15/8515","by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 9055","url":"https://www.law.cornell.edu/uscode/text/15/9055","by":{"0":"21"}},{"t":"usc","label":"16 U.S.C. § 410cc-35","url":"https://www.law.cornell.edu/uscode/text/16/410cc-35","by":{"0":"21"}},{"t":"usc","label":"18 U.S.C. § 1015","url":"https://www.law.cornell.edu/uscode/text/18/1015","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 611","url":"https://www.law.cornell.edu/uscode/text/18/611","stext":{"head":"§611. Voting by aliens","paras":[[0,"(a) It shall be unlawful for any alien to vote in any election held solely or in part for the purpose of electing a candidate for the office of President, Vice President, Presidential elector, Member of the Senate, Member of the House of Representatives, Delegate from the District of Columbia, or Resident Commissioner, unless—"],[1,"(1) the election is held partly for some other purpose;"],[1,"(2) aliens are authorized to vote for such other purpose under a State constitution or statute or a local ordinance; and"],[1,"(3) voting for such other purpose is conducted independently of voting for a candidate for such Federal offices, in such a manner that an alien has the opportunity to vote for such other purpose, but not an opportunity to vote for a candidate for any one or more of such Federal offices."],[0,"(b) Any person who violates this section shall be fined under this title, imprisoned not more than one year, or both."],[0,"(c) Subsection (a) does not apply to an alien if—"],[1,"(1) each natural parent of the alien (or, in the case of an adopted alien, each adoptive parent of the alien) is or was a citizen (whether by birth or naturalization);"],[1,"(2) the alien permanently resided in the United States prior to attaining the age of 16; and"],[1,"(3) the alien reasonably believed at the time of voting in violation of such subsection that he or she was a citizen of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/611?type=usc&year=mostrecent&link-type=html"},"head":"§611. Voting by aliens","tname":"Crimes and Criminal Procedure","by":{"0":"6","2":"10","5":"34"}},{"t":"usc","label":"25 U.S.C. § 2708","url":"https://www.law.cornell.edu/uscode/text/25/2708","by":{"0":"21"}},{"t":"usc","label":"29 U.S.C. § 2635","url":"https://www.law.cornell.edu/uscode/text/29/2635","by":{"0":"21"}},{"t":"usc","label":"41 U.S.C. § 8502","url":"https://www.law.cornell.edu/uscode/text/41/8502","by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 10267","url":"https://www.law.cornell.edu/uscode/text/42/10267","by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 1395vv","url":"https://www.law.cornell.edu/uscode/text/42/1395vv","by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","by":{"0":"21"}},{"t":"usc","label":"47 U.S.C. § 218","url":"https://www.law.cornell.edu/uscode/text/47/218","by":{"0":"21"}},{"t":"usc","label":"5 U.S.C. § 9008","url":"https://www.law.cornell.edu/uscode/text/5/9008","by":{"0":"21"}},{"t":"usc","label":"52 U.S.C. § 20501","url":"https://www.law.cornell.edu/uscode/text/52/20501","subs":["(b)","(a)(3)","(b)(1)"],"stext":{"head":"§20501. Findings and purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the right of citizens of the United States to vote is a fundamental right;"],[1,"(2) it is the duty of the Federal, State, and local governments to promote the exercise of that right; and"],[1,"(3) discriminatory and unfair registration laws and procedures can have a direct and damaging effect on voter participation in elections for Federal office and disproportionately harm voter participation by various groups, including racial minorities."],[0,"(b) Purposes"],[0,"The purposes of this chapter are—"],[1,"(1) to establish procedures that will increase the number of eligible citizens who register to vote in elections for Federal office;"],[1,"(2) to make it possible for Federal, State, and local governments to implement this chapter in a manner that enhances the participation of eligible citizens as voters in elections for Federal office;"],[1,"(3) to protect the integrity of the electoral process; and"],[1,"(4) to ensure that accurate and current voter registration rolls are maintained."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20501?type=usc&year=mostrecent&link-type=html"},"head":"§20501. Findings and purposes","tname":"Voting and Elections","by":{"0":"1, 5, 16, 29, 42, 49, 50","1":"2, 8, 34, 35, 42","2":"1","4":"1","5":"36, 50, 21, 3, 1","6":"3, 4, 18"}},{"t":"usc","label":"52 U.S.C. § 20503","url":"https://www.law.cornell.edu/uscode/text/52/20503","subs":["(a)","(b)"],"stext":{"head":"§20503. National procedures for voter registration for elections for Federal office","paras":[[0,"(a) In general"],[0,"Except as provided in subsection (b), notwithstanding any other Federal or State law, in addition to any other method of voter registration provided for under State law, each State shall establish procedures to register to vote in elections for Federal office—"],[1,"(1) by application made simultaneously with an application for a motor vehicle driver's license pursuant to section 20504 of this title;"],[1,"(2) by mail application pursuant to section 20505 of this title; and"],[1,"(3) by application in person—"],[2,"(A) at the appropriate registration site designated with respect to the residence of the applicant in accordance with State law; and"],[2,"(B) at a Federal, State, or nongovernmental office designated under section 20506 of this title."],[0,"(b) Nonapplicability to certain States"],[0,"This chapter does not apply to a State described in either or both of the following paragraphs:"],[1,"(1) A State in which, under law that is in effect continuously on and after August 1, 1994, there is no voter registration requirement for any voter in the State with respect to an election for Federal office."],[1,"(2) A State in which, under law that is in effect continuously on and after August 1, 1994, or that was enacted on or prior to August 1, 1994, and by its terms is to come into effect upon the enactment of this chapter, so long as that law remains in effect, all voters in the State may register to vote at the polling place at the time of voting in a general election for Federal office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20503?type=usc&year=mostrecent&link-type=html"},"head":"§20503. National procedures for voter registration for elections for Federal office","tname":"Voting and Elections","by":{"0":"42","1":"8, 34, 35, 42, 8, 34, 35, 42"}},{"t":"usc","label":"52 U.S.C. § 20504","url":"https://www.law.cornell.edu/uscode/text/52/20504","subs":["(c)(2)","(c)(2)(B)(ii)","(c)(1)","(c)(2)(C)(i)"],"stext":{"head":"§20504. Simultaneous application for voter registration and application for motor vehicle driver's license","paras":[[0,"(a) In general"],[0,"(1) Each State motor vehicle driver's license application (including any renewal application) submitted to the appropriate State motor vehicle authority under State law shall serve as an application for voter registration with respect to elections for Federal office unless the applicant fails to sign the voter registration application."],[0,"(2) An application for voter registration submitted under paragraph (1) shall be considered as updating any previous voter registration by the applicant."],[0,"(b) Limitation on use of information"],[0,"No information relating to the failure of an applicant for a State motor vehicle driver's license to sign a voter registration application may be used for any purpose other than voter registration."],[0,"(c) Forms and procedures"],[0,"(1) Each State shall include a voter registration application form for elections for Federal office as part of an application for a State motor vehicle driver's license."],[0,"(2) The voter registration application portion of an application for a State motor vehicle driver's license—"],[1,"(A) may not require any information that duplicates information required in the driver's license portion of the form (other than a second signature or other information necessary under subparagraph (C));"],[1,"(B) may require only the minimum amount of information necessary to—"],[2,"(i) prevent duplicate voter registrations; and"],[2,"(ii) enable State election officials to assess the eligibility of the applicant and to administer voter registration and other parts of the election process;"],[1,"(C) shall include a statement that—"],[2,"(i) states each eligibility requirement (including citizenship);"],[2,"(ii) contains an attestation that the applicant meets each such requirement; and"],[2,"(iii) requires the signature of the applicant, under penalty of perjury;"],[1,"(D) shall include, in print that is identical to that used in the attestation portion of the application—"],[2,"(i) the information required in section 20507(a)(5)(A) and (B) of this title;"],[2,"(ii) a statement that, if an applicant declines to register to vote, the fact that the applicant has declined to register will remain confidential and will be used only for voter registration purposes; and"],[2,"(iii) a statement that if an applicant does register to vote, the office at which the applicant submits a voter registration application will remain confidential and will be used only for voter registration purposes; and"],[1,"(E) shall be made available (as submitted by the applicant, or in machine readable or other format) to the appropriate State election official as provided by State law."],[0,"(d) Change of address"],[0,"Any change of address form submitted in accordance with State law for purposes of a State motor vehicle driver's license shall serve as notification of change of address for voter registration with respect to elections for Federal office for the registrant involved unless the registrant states on the form that the change of address is not for voter registration purposes."],[0,"(e) Transmittal deadline"],[0,"(1) Subject to paragraph (2), a completed voter registration portion of an application for a State motor vehicle driver's license accepted at a State motor vehicle authority shall be transmitted to the appropriate State election official not later than 10 days after the date of acceptance."],[0,"(2) If a registration application is accepted within 5 days before the last day for registration to vote in an election, the application shall be transmitted to the appropriate State election official not later than 5 days after the date of acceptance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20504?type=usc&year=mostrecent&link-type=html"},"head":"§20504. Simultaneous application for voter registration and application for motor vehicle driver's license","tname":"Voting and Elections","by":{"0":"42, 45, 13, 25, 31, 43","1":"8, 34, 35, 42, 8, 34, 35, 42","2":"12","3":"16","5":"35, 35","6":"18, 20–22, 41"}},{"t":"usc","label":"52 U.S.C. § 20505","url":"https://www.law.cornell.edu/uscode/text/52/20505","subs":["(a)(1)","(a)(2)","(b)"],"stext":{"head":"§20505. Mail registration","paras":[[0,"(a) Form"],[0,"(1) Each State shall accept and use the mail voter registration application form prescribed by the Federal Election Commission pursuant to section 20508(a)(2) of this title for the registration of voters in elections for Federal office."],[0,"(2) In addition to accepting and using the form described in paragraph (1), a State may develop and use a mail voter registration form that meets all of the criteria stated in section 20508(b) of this title for the registration of voters in elections for Federal office."],[0,"(3) A form described in paragraph (1) or (2) shall be accepted and used for notification of a registrant's change of address."],[0,"(b) Availability of forms"],[0,"The chief State election official of a State shall make the forms described in subsection (a) available for distribution through governmental and private entities, with particular emphasis on making them available for organized voter registration programs."],[0,"(c) First-time voters"],[0,"(1) Subject to paragraph (2), a State may by law require a person to vote in person if—"],[1,"(A) the person was registered to vote in a jurisdiction by mail; and"],[1,"(B) the person has not previously voted in that jurisdiction."],[0,"(2) Paragraph (1) does not apply in the case of a person—"],[1,"(A) who is entitled to vote by absentee ballot under the Uniformed and Overseas Citizens Absentee Voting Act [52 U.S.C. 20301 et seq.];"],[1,"(B) who is provided the right to vote otherwise than in person under section 20102(b)(2)(B)(ii) of this title; or"],[1,"(C) who is entitled to vote otherwise than in person under any other Federal law."],[0,"(d) Undelivered notices"],[0,"If a notice of the disposition of a mail voter registration application under section 20507(a)(2) of this title is sent by nonforwardable mail and is returned undelivered, the registrar may proceed in accordance with section 20507(d) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20505?type=usc&year=mostrecent&link-type=html"},"head":"§20505. Mail registration","tname":"Voting and Elections","by":{"0":"5, 12, 18, 29, 31, 45","1":"8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42","2":"9–10, 14–15","3":"14, 19, 14","5":"3, 4, 19, 3, 21","6":"2, 4, 13, 18, 21, 28"}},{"t":"usc","label":"52 U.S.C. § 20506","url":"https://www.law.cornell.edu/uscode/text/52/20506","subs":["(a)(6)(A)","(a)(2)","(a)(3)","(a)(4)","(a)(4)(A)(i)","(a)(6)(A)(i)","(a)(6)(A)(ii)"],"stext":{"head":"§20506. Voter registration agencies","paras":[[0,"(a) Designation"],[0,"(1) Each State shall designate agencies for the registration of voters in elections for Federal office."],[0,"(2) Each State shall designate as voter registration agencies—"],[1,"(A) all offices in the State that provide public assistance; and"],[1,"(B) all offices in the State that provide State-funded programs primarily engaged in providing services to persons with disabilities."],[0,"(3)(A) In addition to voter registration agencies designated under paragraph (2), each State shall designate other offices within the State as voter registration agencies."],[0,"(B) Voter registration agencies designated under subparagraph (A) may include—"],[1,"(i) State or local government offices such as public libraries, public schools, offices of city and county clerks (including marriage license bureaus), fishing and hunting license bureaus, government revenue offices, unemployment compensation offices, and offices not described in paragraph (2)(B) that provide services to persons with disabilities; and"],[1,"(ii) Federal and nongovernmental offices, with the agreement of such offices."],[0,"(4)(A) At each voter registration agency, the following services shall be made available:"],[1,"(i) Distribution of mail voter registration application forms in accordance with paragraph (6)."],[1,"(ii) Assistance to applicants in completing voter registration application forms, unless the applicant refuses such assistance."],[1,"(iii) Acceptance of completed voter registration application forms for transmittal to the appropriate State election official."],[0,"(B) If a voter registration agency designated under paragraph (2)(B) provides services to a person with a disability at the person's home, the agency shall provide the services described in subparagraph (A) at the person's home."],[0,"(5) A person who provides service described in paragraph (4) shall not—"],[1,"(A) seek to influence an applicant's political preference or party registration;"],[1,"(B) display any such political preference or party allegiance;"],[1,"(C) make any statement to an applicant or take any action the purpose or effect of which is to discourage the applicant from registering to vote; or"],[1,"(D) make any statement to an applicant or take any action the purpose or effect of which is to lead the applicant to believe that a decision to register or not to register has any bearing on the availability of services or benefits."],[0,"(6) A voter registration agency that is an office that provides service or assistance in addition to conducting voter registration shall—"],[1,"(A) distribute with each application for such service or assistance, and with each recertification, renewal, or change of address form relating to such service or assistance—"],[2,"(i) the mail voter registration application form described in section 20508(a)(2) of this title, including a statement that—"],[3,"(I) specifies each eligibility requirement (including citizenship);"],[3,"(II) contains an attestation that the applicant meets each such requirement; and"],[3,"(III) requires the signature of the applicant, under penalty of perjury; or"],[2,"(ii) the office's own form if it is equivalent to the form described in section 20508(a)(2) of this title,"],[1,"unless the applicant, in writing, declines to register to vote;"],[1,"(B) provide a form that includes—"],[2,"(i) the question, \"If you are not registered to vote where you live now, would you like to apply to register to vote here today?\";"],[2,"(ii) if the agency provides public assistance, the statement, \"Applying to register or declining to register to vote will not affect the amount of assistance that you will be provided by this agency.\";"],[2,"(iii) boxes for the applicant to check to indicate whether the applicant would like to register or declines to register to vote (failure to check either box being deemed to constitute a declination to register for purposes of subparagraph (C)), together with the statement (in close proximity to the boxes and in prominent type), \"IF YOU DO NOT CHECK EITHER BOX, YOU WILL BE CONSIDERED TO HAVE DECIDED NOT TO REGISTER TO VOTE AT THIS TIME.\";"],[2,"(iv) the statement, \"If you would like help in filling out the voter registration application form, we will help you. The decision whether to seek or accept help is yours. You may fill out the application form in private.\"; and"],[2,"(v) the statement, \"If you believe that someone has interfered with your right to register or to decline to register to vote, your right to privacy in deciding whether to register or in applying to register to vote, or your right to choose your own political party or other political preference, you may file a complaint with __________.\", the blank being filled by the name, address, and telephone number of the appropriate official to whom such a complaint should be addressed; and"],[1,"(C) provide to each applicant who does not decline to register to vote the same degree of assistance with regard to the completion of the registration application form as is provided by the office with regard to the completion of its own forms, unless the applicant refuses such assistance."],[0,"(7) No information relating to a declination to register to vote in connection with an application made at an office described in paragraph (6) may be used for any purpose other than voter registration."],[0,"(b) Federal Government and private sector cooperation"],[0,"All departments, agencies, and other entities of the executive branch of the Federal Government shall, to the greatest extent practicable, cooperate with the States in carrying out subsection (a), and all nongovernmental entities are encouraged to do so."],[0,"(c) Armed Forces recruitment offices"],[0,"(1) Each State and the Secretary of Defense shall jointly develop and implement procedures for persons to apply to register to vote at recruitment offices of the Armed Forces of the United States."],[0,"(2) A recruitment office of the Armed Forces of the United States shall be considered to be a voter registration agency designated under subsection (a)(2) for all purposes of this chapter."],[0,"(d) Transmittal deadline"],[0,"(1) Subject to paragraph (2), a completed registration application accepted at a voter registration agency shall be transmitted to the appropriate State election official not later than 10 days after the date of acceptance."],[0,"(2) If a registration application is accepted within 5 days before the last day for registration to vote in an election, the application shall be transmitted to the appropriate State election official not later than 5 days after the date of acceptance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20506?type=usc&year=mostrecent&link-type=html"},"head":"§20506. Voter registration agencies","tname":"Voting and Elections","by":{"0":"5, 42, 1, 5, 12, 15, 18, 27-30, 43","1":"8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42, 8, 34, 35, 42","2":"13, 15","3":"19, 12, 13, 18, 19","5":"35, 2, 4, 7, 30","6":"5, 18, 30, 31, 41"}},{"t":"usc","label":"52 U.S.C. § 20507","url":"https://www.law.cornell.edu/uscode/text/52/20507","subs":["(c)(2)(A)","(a)(1)","(a)(2)","(a)(3)","(a)(3)(A)","(a)(3)(B)","(a)(4)","(a)(4)(A)","(a)(4)(B)","(b)","(b)(1)","(b)(2)","(c)(1)","(c)(2)(B)","(c)(2)(B)(i)","(d)","(c)(2)","(d)(1)","(d)(3)","(f)","(i)(1)"],"stext":{"head":"§20507. Requirements with respect to administration of voter registration","paras":[[0,"(a) In general"],[0,"In the administration of voter registration for elections for Federal office, each State shall—"],[1,"(1) ensure that any eligible applicant is registered to vote in an election—"],[2,"(A) in the case of registration with a motor vehicle application under section 20504 of this title, if the valid voter registration form of the applicant is submitted to the appropriate State motor vehicle authority not later than the lesser of 30 days, or the period provided by State law, before the date of the election;"],[2,"(B) in the case of registration by mail under section 20505 of this title, if the valid voter registration form of the applicant is postmarked not later than the lesser of 30 days, or the period provided by State law, before the date of the election;"],[2,"(C) in the case of registration at a voter registration agency, if the valid voter registration form of the applicant is accepted at the voter registration agency not later than the lesser of 30 days, or the period provided by State law, before the date of the election; and"],[2,"(D) in any other case, if the valid voter registration form of the applicant is received by the appropriate State election official not later than the lesser of 30 days, or the period provided by State law, before the date of the election;"],[1,"(2) require the appropriate State election official to send notice to each applicant of the disposition of the application;"],[1,"(3) provide that the name of a registrant may not be removed from the official list of eligible voters except—"],[2,"(A) at the request of the registrant;"],[2,"(B) as provided by State law, by reason of criminal conviction or mental incapacity; or"],[2,"(C) as provided under paragraph (4);"],[1,"(4) conduct a general program that makes a reasonable effort to remove the names of ineligible voters from the official lists of eligible voters by reason of—"],[2,"(A) the death of the registrant; or"],[2,"(B) a change in the residence of the registrant, in accordance with subsections (b), (c), and (d);"],[1,"(5) inform applicants under sections 20504, 20505, and 20506 of this title of—"],[2,"(A) voter eligibility requirements; and"],[2,"(B) penalties provided by law for submission of a false voter registration application; and"],[1,"(6) ensure that the identity of the voter registration agency through which any particular voter is registered is not disclosed to the public."],[0,"(b) Confirmation of voter registration"],[0,"Any State program or activity to protect the integrity of the electoral process by ensuring the maintenance of an accurate and current voter registration roll for elections for Federal office—"],[1,"(1) shall be uniform, nondiscriminatory, and in compliance with the Voting Rights Act of 1965 (42 U.S.C. 1973 et seq.) [now 52 U.S.C. 10301 et seq.]; and"],[1,"(2) shall not result in the removal of the name of any person from the official list of voters registered to vote in an election for Federal office by reason of the person's failure to vote, except that nothing in this paragraph may be construed to prohibit a State from using the procedures described in subsections (c) and (d) to remove an individual from the official list of eligible voters if the individual—"],[2,"(A) has not either notified the applicable registrar (in person or in writing) or responded during the period described in subparagraph (B) to the notice sent by the applicable registrar; and then"],[2,"(B) has not voted or appeared to vote in 2 or more consecutive general elections for Federal office."],[0,"(c) Voter removal programs"],[0,"(1) A State may meet the requirement of subsection (a)(4) by establishing a program under which—"],[1,"(A) change-of-address information supplied by the Postal Service through its licensees is used to identify registrants whose addresses may have changed; and"],[1,"(B) if it appears from information provided by the Postal Service that—"],[2,"(i) a registrant has moved to a different residence address in the same registrar's jurisdiction in which the registrant is currently registered, the registrar changes the registration records to show the new address and sends the registrant a notice of the change by forwardable mail and a postage prepaid pre-addressed return form by which the registrant may verify or correct the address information; or"],[2,"(ii) the registrant has moved to a different residence address not in the same registrar's jurisdiction, the registrar uses the notice procedure described in subsection (d)(2) to confirm the change of address."],[0,"(2)(A) A State shall complete, not later than 90 days prior to the date of a primary or general election for Federal office, any program the purpose of which is to systematically remove the names of ineligible voters from the official lists of eligible voters."],[0,"(B) Subparagraph (A) shall not be construed to preclude—"],[1,"(i) the removal of names from official lists of voters on a basis described in paragraph (3)(A) or (B) or (4)(A) of subsection (a); or"],[1,"(ii) correction of registration records pursuant to this chapter."],[0,"(d) Removal of names from voting rolls"],[0,"(1) A State shall not remove the name of a registrant from the official list of eligible voters in elections for Federal office on the ground that the registrant has changed residence unless the registrant—"],[1,"(A) confirms in writing that the registrant has changed residence to a place outside the registrar's jurisdiction in which the registrant is registered; or"],[1,"(B)(i) has failed to respond to a notice described in paragraph (2); and"],[1,"(ii) has not voted or appeared to vote (and, if necessary, correct the registrar's record of the registrant's address) in an election during the period beginning on the date of the notice and ending on the day after the date of the second general election for Federal office that occurs after the date of the notice."],[0,"(2) A notice is described in this paragraph if it is a postage prepaid and pre-addressed return card, sent by forwardable mail, on which the registrant may state his or her current address, together with a notice to the following effect:"],[1,"(A) If the registrant did not change his or her residence, or changed residence but remained in the registrar's jurisdiction, the registrant should return the card not later than the time provided for mail registration under subsection (a)(1)(B). If the card is not returned, affirmation or confirmation of the registrant's address may be required before the registrant is permitted to vote in a Federal election during the period beginning on the date of the notice and ending on the day after the date of the second general election for Federal office that occurs after the date of the notice, and if the registrant does not vote in an election during that period the registrant's name will be removed from the list of eligible voters."],[1,"(B) If the registrant has changed residence to a place outside the registrar's jurisdiction in which the registrant is registered, information concerning how the registrant can continue to be eligible to vote."],[0,"(3) A voting registrar shall correct an official list of eligible voters in elections for Federal office in accordance with change of residence information obtained in conformance with this subsection."],[0,"(e) Procedure for voting following failure to return card"],[0,"(1) A registrant who has moved from an address in the area covered by a polling place to an address in the same area shall, notwithstanding failure to notify the registrar of the change of address prior to the date of an election, be permitted to vote at that polling place upon oral or written affirmation by the registrant of the change of address before an election official at that polling place."],[0,"(2)(A) A registrant who has moved from an address in the area covered by one polling place to an address in an area covered by a second polling place within the same registrar's jurisdiction and the same congressional district and who has failed to notify the registrar of the change of address prior to the date of an election, at the option of the registrant—"],[1,"(i) shall be permitted to correct the voting records and vote at the registrant's former polling place, upon oral or written affirmation by the registrant of the new address before an election official at that polling place; or"],[1,"(ii)(I) shall be permitted to correct the voting records and vote at a central location within the same registrar's jurisdiction designated by the registrar where a list of eligible voters is maintained, upon written affirmation by the registrant of the new address on a standard form provided by the registrar at the central location; or"],[1,"(II) shall be permitted to correct the voting records for purposes of voting in future elections at the appropriate polling place for the current address and, if permitted by State law, shall be permitted to vote in the present election, upon confirmation by the registrant of the new address by such means as are required by law."],[0,"(B) If State law permits the registrant to vote in the current election upon oral or written affirmation by the registrant of the new address at a polling place described in subparagraph (A)(i) or (A)(ii)(II), voting at the other locations described in subparagraph (A) need not be provided as options."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20507?type=usc&year=mostrecent&link-type=html"},"head":"§20507. Requirements with respect to administration of voter registration","tname":"Voting and Elections","by":{"0":"5, 6, 14, 16, 41, 43-48, 50, 51, 2, 6, 41, 42, 44, 46-49","1":"8, 34, 35, 42, 8, 34, 35, 42, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9","2":"6","5":"48, 43, 48, 38-40, 43, 44, 43, 39, 44, 1, 40, 43, 4, 33, 38, 41, 43, 44, 35, 39, 44, 45, 43, 43, 43, 43","6":"3, 5, 12, 38–42, 44, 45, 47, 51"}},{"t":"usc","label":"52 U.S.C. § 20508","url":"https://www.law.cornell.edu/uscode/text/52/20508","subs":["(b)(1)","(a)(2)","(b)","(b)(2)"],"stext":{"head":"§20508. Federal coordination and regulations","paras":[[0,"(a) In general"],[0,"The Election Assistance Commission—"],[1,"(1) in consultation with the chief election officers of the States, shall prescribe such regulations as are necessary to carry out paragraphs (2) and (3);"],[1,"(2) in consultation with the chief election officers of the States, shall develop a mail voter registration application form for elections for Federal office;"],[1,"(3) not later than June 30 of each odd-numbered year, shall submit to the Congress a report assessing the impact of this chapter on the administration of elections for Federal office during the preceding 2-year period and including recommendations for improvements in Federal and State procedures, forms, and other matters affected by this chapter; and"],[1,"(4) shall provide information to the States with respect to the responsibilities of the States under this chapter."],[0,"(b) Contents of mail voter registration form"],[0,"The mail voter registration form developed under subsection (a)(2)—"],[1,"(1) may require only such identifying information (including the signature of the applicant) and other information (including data relating to previous registration by the applicant), as is necessary to enable the appropriate State election official to assess the eligibility of the applicant and to administer voter registration and other parts of the election process;"],[1,"(2) shall include a statement that—"],[2,"(A) specifies each eligibility requirement (including citizenship);"],[2,"(B) contains an attestation that the applicant meets each such requirement; and"],[2,"(C) requires the signature of the applicant, under penalty of perjury;"],[1,"(3) may not include any requirement for notarization or other formal authentication; and"],[1,"(4) shall include, in print that is identical to that used in the attestation portion of the application—"],[2,"(i) the information required in section 20507(a)(5)(A) and (B) of this title;"],[2,"(ii) a statement that, if an applicant declines to register to vote, the fact that the applicant has declined to register will remain confidential and will be used only for voter registration purposes; and"],[2,"(iii) a statement that if an applicant does register to vote, the office at which the applicant submits a voter registration application will remain confidential and will be used only for voter registration purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20508?type=usc&year=mostrecent&link-type=html"},"head":"§20508. Federal coordination and regulations","tname":"Voting and Elections","by":{"0":"5, 23, 25, 29, 1, 2, 5, 12, 13, 15, 18, 20, 22, 23, 27, 43","1":"9, 9, 9, 9","2":"8–15, 19, 22","3":"14, 12, 13, 14","5":"1, 4, 19, 21, 35","6":"2, 4, 10, 11, 13, 16–18, 20–23, 26, 28, 41"}},{"t":"usc","label":"52 U.S.C. § 20510","url":"https://www.law.cornell.edu/uscode/text/52/20510","subs":["(b)"],"stext":{"head":"§20510. Civil enforcement and private right of action","paras":[[0,"(a) Attorney General"],[0,"The Attorney General may bring a civil action in an appropriate district court for such declaratory or injunctive relief as is necessary to carry out this chapter."],[0,"(b) Private right of action"],[0,"(1) A person who is aggrieved by a violation of this chapter may provide written notice of the violation to the chief election official of the State involved."],[0,"(2) If the violation is not corrected within 90 days after receipt of a notice under paragraph (1), or within 20 days after receipt of the notice if the violation occurred within 120 days before the date of an election for Federal office, the aggrieved person may bring a civil action in an appropriate district court for declaratory or injunctive relief with respect to the violation."],[0,"(3) If the violation occurred within 30 days before the date of an election for Federal office, the aggrieved person need not provide notice to the chief election official of the State under paragraph (1) before bringing a civil action under paragraph (2)."],[0,"(c) Attorney's fees"],[0,"In a civil action under this section, the court may allow the prevailing party (other than the United States) reasonable attorney fees, including litigation expenses, and costs."],[0,"(d) Relation to other laws"],[0,"(1) The rights and remedies established by this section are in addition to all other rights and remedies provided by law, and neither the rights and remedies established by this section nor any other provision of this chapter shall supersede, restrict, or limit the application of the Voting Rights Act of 1965 (42 U.S.C. 1973 et seq.) [now 52 U.S.C. 10301 et seq.]."],[0,"(2) Nothing in this chapter authorizes or requires conduct that is prohibited by the Voting Rights Act of 1965 (42 U.S.C. 1973 et seq.) [now 52 U.S.C. 10301 et seq.]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20510?type=usc&year=mostrecent&link-type=html"},"head":"§20510. Civil enforcement and private right of action","tname":"Voting and Elections","by":{"0":"25","1":"9","6":"22–23"}},{"t":"usc","label":"54 U.S.C. § 312304","url":"https://www.law.cornell.edu/uscode/text/54/312304","by":{"0":"21"}},{"t":"const","label":"Article I, Section 2","clauses":[["apportionment","Apportionment and the Three-Fifths Clause"]],"by":{"0":"1, 4, 32, 38","2":"21","6":"22"}},{"t":"const","label":"Article I, Section 4","clauses":[["elections-clause","Elections Clause"]],"text":"The Times, Places and Manner of holding Elections for Senators and Representatives, shall be prescribed in each State by the Legislature thereof; but the Congress may at any time by Law make or alter such Regulations, except as to the Places of chusing Senators. The Congress shall assemble at least once in every Year, and such Meeting shall be on the first Monday in December, unless they shall by Law appoint a different Day.","by":{"0":"4, 38","2":"11, 21","6":"26"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"0":"4, 38"}},{"t":"case","label":"American Express Co. v. Italian Colors Restaurant","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Arcia v. Detzner","cite":"908 F. Supp. 2d 1276","y":2012,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/908/1276/","by":{"1":"43"}},{"t":"case","label":"Arcia v. Florida Secretary of State","cite":"772 F.3d 1335","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1335/","sum":"Holding that Kansas and Arizona “failed to meet their evidentiary burden of proving that they cannot enforce their voter qualifications” without DPOC.","sumSrc":"brief:5","by":{"1":"38","4":"1, 16-18, 20, 29, 31, 32, 34, 35, 39-41","5":"36-37, 47","6":"4, 39, 41, 48, 52"}},{"t":"case","label":"Beals v. Virginia Coalition for Immigrant Rights","cite":"2024 WL 4608863","y":2024,"court":"Oct. 30","by":{"1":"12"}},{"t":"case","label":"Brown v. Plata","cite":"563 U.S. 493","y":2011,"id":"2010/09-1233","sc":1,"sum":"The Court held that a court order requiring California to reduce its prison population to remedy unconstitutional conditions in its correctional facilities did not violate the Prison Litigation Reform Act.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Bucklew v. Precythe","cite":"587 U.S. 119","y":2019,"id":"2018/17-8151","sc":1,"sum":"Baze v. Rees, 553 U. S. 35, and Glossip v. Gross, 576 U. S. ___, govern all Eighth Amendment challenges alleging that a method of execution inflicts unconstitutionally cruel pain; petitioner’s as-applied challenge to Missouri’s single-drug execution protocol—that it would cause him severe pain because of his particular medical condition—fails to satisfy the Baze-Glossip test.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"584 U.S. 79","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Evans v. City of Chicago","cite":"10 F.3d 474","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/10/474/","by":{"1":"26"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"General Dynamics Land Systems, Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"1":"32, 33, 35"}},{"t":"case","label":"Husted v. A. Philip Randolph Institute","cite":"584 U.S. 756","y":2018,"id":"2017/16-980","sc":1,"sum":"A case in which the Court upheld Ohio's list-maintenance process against a challenge under under National Voter Registration Act of 1993 (NVRA) and the Help America Vote Act of 2002 (HAVA).","sumSrc":"Oyez","by":{"1":"8","5":"4","6":"3, 5"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"1":"33, 35"}},{"t":"case","label":"Martin v. Wilks","cite":"490 U.S. 755","y":1989,"id":"1988/87-1614","sc":1,"sum":"In a 5-to-4 decision, the Court held that because \"a person cannot be deprived of his legal rights in a proceeding to which he is not a party,\" the white firefighters were not precluded from challenging employment decisions taken pursuant to the consent decrees.","sumSrc":"Oyez","by":{"1":"30","2":"16","5":"14"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Smiley v. Holm","cite":"285 U.S. 355","y":1932,"id":"scdb/1931-045","sc":1,"sum":"1. The function of a state legislature in prescribing the time, place and manner of holding elections for Representatives in Congress under Constitution, Art. 1, § 4, is a law-making function in which the veto power of the state governor participates if, under the state constitution, the governor has that power in the making of state laws.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"Sweeton v. Brown","cite":"27 F.3d 1162","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/27/1162/","by":{"1":"26"}},{"t":"case","label":"Thompson v. United States","cite":"604 U.S. 408","y":2025,"id":"2024/23-1095","sc":1,"sum":"Title 18 U. S. C. §1014, which prohibits “knowingly mak[ing] any false statement,” does not criminalize statements that are misleading but not false.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36"}},{"t":"const","label":"Article II, Section 1, Clause 2","text":"Each State shall appoint, in such Manner as the Legislature thereof may direct, a Number of Electors, equal to the whole Number of Senators and Representatives to which the State may be entitled in the Congress: but no Senator or Representative, or Person holding an Office of Trust or Profit under the United States, shall be appointed an Elector.","by":{"1":"5","5":"25"}},{"t":"const","label":"Amendment XVII","clauses":[["seventeenth-amendment","Seventeenth Amendment"]],"text":"The Senate of the United States shall be composed of two Senators from each State, elected by the people thereof, for six years; and each Senator shall have one vote. The electors in each State shall have the qualifications requisite for electors of the most numerous branch of the State legislatures. When vacancies happen in the representation of any State in the Senate, the executive authority of such State shall issue writs of election to fill such vacancies: Provided, That the legislature of any State may empower the executive thereof to make temporary appointments until the people fill the vacancies by election as the legislature may direct. This amendment shall not be so construed as to affect the election or term of any Senator chosen before it becomes valid as part of the Constitution.","by":{"1":"5"}},{"t":"reg","label":"and rules—Continued: Exec. Order No. 14,248, 90 Fed. Reg. 14,005","url":"https://www.govinfo.gov/link/fr/90/14005","by":{"1":"19"}},{"t":"reg","label":"90 Fed. Reg. 14,006","url":"https://www.govinfo.gov/link/fr/90/14006","by":{"1":"9"}},{"t":"case","label":"City of Warren v. City of Detroit","cite":"495 F.3d 282","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/495/282/","by":{"2":"17"}},{"t":"case","label":"Doe v. Pataki","cite":"481 F.3d 69","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/481/69/","by":{"2":"19"}},{"t":"case","label":"Dunn v. Carey","cite":"808 F.2d 555","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/808/555/","by":{"2":"17"}},{"t":"case","label":"Esteras v. United States","cite":"606 U.S. 185","y":2025,"id":"2024/23-7483","sc":1,"sum":"A district court considering whether to revoke a defendant’s term of supervised release may not consider 18 U. S. C. §3553(a)(2)(A), which covers retribution vis-à-vis the defendant’s underlying criminal offense.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12"}},{"t":"case","label":"Gonzalez v. Arizona","cite":"485 F.3d 1041","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/485/1041/","by":{"2":"11"}},{"t":"case","label":"Kasper v. Bd. of Election Comm’rs. of the City of Chicago","cite":"814 F.2d 332","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/814/332/","by":{"2":"20"}},{"t":"case","label":"Keith v. Volpe","cite":"118 F.3d 1386","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/1386/","sum":"Holding that parties to a consent decree “could not agree to terms which would exceed their authority and supplant state law”.","sumSrc":"brief:2","by":{"2":"20"}},{"t":"case","label":"Local No. 93, Int’l Ass’n. of Firefighters, AFL-CIO C.L.C. v. City of Cleveland","cite":"478 U.S. 501","y":1986,"id":"1985/84-1999","sc":1,"sum":"The Court held that section 706(g) of Title VII does not apply to relief awarded in a consent decree.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Milliken v. Bradley","cite":"433 U.S. 267","y":1977,"id":"1976/76-447","sc":1,"sum":"Yes and yes. In a unanimous decision, the Court affirmed the District Court order, emphasizing \"equitable principles\" in the construction of desegregation plans set forth in Brown v. Board of Education (1955) _.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Navajo Nation v. San Juan Cnty.","cite":"929 F.3d 1270","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/929/1270/","by":{"2":"17"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"2":"18","6":"32, 33"}},{"t":"case","label":"St. Charles Tower, Inc. v. Kurtz","cite":"643 F.3d 264","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/643/264/","by":{"2":"20"}},{"t":"case","label":"State ex rel. Napolitano v. Brown","cite":"982 P. 2d 815","y":1999,"court":"Ariz.","url":"https://www.courtlistener.com/c/P.%202d/982/815/","by":{"2":"19"}},{"t":"case","label":"Sw. Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"2":"13"}},{"t":"case","label":"Util. Air Regulatory Grp. v. E.P.A.","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"17–18"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"2":"5"}},{"t":"const","label":"Amendment XV","clauses":[["fifteenth-amendment","Fifteenth Amendment"]],"text":"The right of citizens of the United States to vote shall not be denied or abridged by the United States or by any State on account of race, color, or previous condition of servitude-- The Congress shall have power to enforce this article by appropriate legislation.","by":{"2":"5"}},{"t":"usc","label":"18 U.S.C. § 1815","url":"https://www.law.cornell.edu/uscode/text/18/1815","by":{"2":"10"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"2":"2"}},{"t":"usc","label":"52 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/52/10101","stext":{"head":"§10101. Voting rights","paras":[[0,"(a) Race, color, or previous condition not to affect right to vote; uniform standards for voting qualifications; errors or omissions from papers; literacy tests; agreements between Attorney General and State or local authorities; definitions"],[0,"(1) All citizens of the United States who are otherwise qualified by law to vote at any election by the people in any State, Territory, district, county, city, parish, township, school district, municipality, or other territorial subdivision, shall be entitled and allowed to vote at all such elections, without distinction of race, color, or previous condition of servitude; any constitution, law, custom, usage, or regulation of any State or Territory, or by or under its authority, to the contrary notwithstanding."],[0,"(2) No person acting under color of law shall—"],[1,"(A) in determining whether any individual is qualified under State law or laws to vote in any election, apply any standard, practice, or procedure different from the standards, practices, or procedures applied under such law or laws to other individuals within the same county, parish, or similar political subdivision who have been found by State officials to be qualified to vote;"],[1,"(B) deny the right of any individual to vote in any election because of an error or omission on any record or paper relating to any application, registration, or other act requisite to voting, if such error or omission is not material in determining whether such individual is qualified under State law to vote in such election; or"],[1,"(C) employ any literacy test as a qualification for voting in any election unless (i) such test is administered to each individual and is conducted wholly in writing, and (ii) a certified copy of the test and of the answers given by the individual is furnished to him within twenty-five days of the submission of his request made within the period of time during which records and papers are required to be retained and preserved pursuant to title III of the Civil Rights Act of 1960 [52 U.S.C. 20701 et seq.]: Provided, however, That the Attorney General may enter into agreements with appropriate State or local authorities that preparation, conduct, and maintenance of such tests in accordance with the provisions of applicable State or local law, including such special provisions as are necessary in the preparation, conduct, and maintenance of such tests for persons who are blind or otherwise physically handicapped, meet the purposes of this subparagraph and constitute compliance therewith."],[0,"(3) For purposes of this subsection—"],[1,"(A) the term \"vote\" shall have the same meaning as in subsection (e) of this section;"],[1,"(B) the phrase \"literacy test\" includes any test of the ability to read, write, understand, or interpret any matter."],[0,"(b) Intimidation, threats, or coercion"],[0,"No person, whether acting under color of law or otherwise, shall intimidate, threaten, coerce, or attempt to intimidate, threaten, or coerce any other person for the purpose of interfering with the right of such other person to vote or to vote as he may choose, or of causing such other person to vote for, or not to vote for, any candidate for the office of President, Vice President, presidential elector, Member of the Senate, or Member of the House of Representatives, Delegates or Commissioners from the Territories or possessions, at any general, special, or primary election held solely or in part for the purpose of selecting or electing any such candidate."],[0,"(c) Preventive relief; injunction; rebuttable literacy presumption; liability of United States for costs; State as party defendant"],[0,"Whenever any person has engaged or there are reasonable grounds to believe that any person is about to engage in any act or practice which would deprive any other person of any right or privilege secured by subsection (a) or (b), the Attorney General may institute for the United States, or in the name of the United States, a civil action or other proper proceeding for preventive relief, including an application for a permanent or temporary injunction, restraining order, or other order. If in any such proceeding literacy is a relevant fact there shall be a rebuttable presumption that any person who has not been adjudged an incompetent and who has completed the sixth grade in a public school in, or a private school accredited by, any State or territory, the District of Columbia, or the Commonwealth of Puerto Rico where instruction is carried on predominantly in the English language, possesses sufficient literacy, comprehension, and intelligence to vote in any election. In any proceeding hereunder the United States shall be liable for costs the same as a private person. Whenever, in a proceeding instituted under this subsection any official of a State or subdivision thereof is alleged to have committed any act or practice constituting a deprivation of any right or privilege secured by subsection (a), the act or practice shall also be deemed that of the State and the State may be joined as a party defendant and, if, prior to the institution of such proceeding, such official has resigned or has been relieved of his office and no successor has assumed such office, the proceeding may be instituted against the State."],[0,"(d) Jurisdiction; exhaustion of other remedies"],[0,"The district courts of the United States shall have jurisdiction of proceedings instituted pursuant to this section and shall exercise the same without regard to whether the party aggrieved shall have exhausted any administrative or other remedies that may be provided by law."],[0,"(e) Order qualifying person to vote; application; hearing; voting referees; transmittal of report and order; certificate of qualification; definitions"],[0,"In any proceeding instituted pursuant to subsection (c) in the event the court finds that any person has been deprived on account of race or color of any right or privilege secured by subsection (a), the court shall upon request of the Attorney General and after each party has been given notice and the opportunity to be heard make a finding whether such deprivation was or is pursuant to a pattern or practice. If the court finds such pattern or practice, any person of such race or color resident within the affected area shall, for one year and thereafter until the court subsequently finds that such pattern or practice has ceased, be entitled, upon his application therefor, to an order declaring him qualified to vote, upon proof that at any election or elections (1) he is qualified under State law to vote, and (2) he has since such finding by the court been (a) deprived of or denied under color of law the opportunity to register to vote or otherwise to qualify to vote, or (b) found not qualified to vote by any person acting under color of law. Such order shall be effective as to any election held within the longest period for which such applicant could have been registered or otherwise qualified under State law at which the applicant's qualifications would under State law entitle him to vote."],[0,"Notwithstanding any inconsistent provision of State law or the action of any State officer or court, an applicant so declared qualified to vote shall be permitted to vote in any such election. The Attorney General shall cause to be transmitted certified copies of such order to the appropriate election officers. The refusal by any such officer with notice of such order to permit any person so declared qualified to vote to vote at an appropriate election shall constitute contempt of court."],[0,"An application for an order pursuant to this subsection shall be heard within ten days, and the execution of any order disposing of such application shall not be stayed if the effect of such stay would be to delay the effectiveness of the order beyond the date of any election at which the applicant would otherwise be enabled to vote."],[0,"The court may appoint one or more persons who are qualified voters in the judicial district, to be known as voting referees, who shall subscribe to the oath of office required by section 3331 of title 5, to serve for such period as the court shall determine, to receive such applications and to take evidence and report to the court findings as to whether or not at any election or elections (1) any such applicant is qualified under State law to vote, and (2) he has since the finding by the court heretofore specified been (a) deprived of or denied under color of law the opportunity to register to vote or otherwise to qualify to vote, or (b) found not qualified to vote by any person acting under color of law. In a proceeding before a voting referee, the applicant shall be heard ex parte at such times and places as the court shall direct. His statement under oath shall be prima facie evidence as to his age, residence, and his prior efforts to register or otherwise qualify to vote. Where proof of literacy or an understanding of other subjects is required by valid provisions of State law, the answer of the applicant, if written, shall be included in such report to the court; if oral, it shall be taken down stenographically and a transcription included in such report to the court."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10101?type=usc&year=mostrecent&link-type=html"},"head":"§10101. Voting rights","tname":"Voting and Elections","by":{"2":"6","6":"19"}},{"t":"rule","label":"Fed. R. Civ. P. 19","url":"https://www.law.cornell.edu/rules/frcp/rule_19","by":{"2":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 24","url":"https://www.law.cornell.edu/rules/frcp/rule_24","by":{"2":"16","3":"26"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)"],"by":{"2":"16","3":"10, 12, 20, 23, 25, 26, 27","5":"11"}},{"t":"case","label":"Celotex Corp. v. Edwards","cite":"514 U.S. 300","y":1995,"id":"1994/93-1504","sc":1,"sum":"The United States District Court for the Northern District of Texas entered a judgment in favor of respondents and against petitioner Celotex Corp. To stay execution of the judgment pending appeal, petitioner posted a supersedeas bond, with an insurance company (Northbrook) serving as surety. After the Fifth Circuit affirmed the judgment, Celotex filed for Chapter 11 bankruptcy in the Bankruptcy Court for the Middle …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22, 23, 27"}},{"t":"case","label":"Foster v. Stanek","cite":"689 F. Supp. 3d 975","y":2023,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/689/975/","by":{"3":"25"}},{"t":"case","label":"Gonzalez v. Arizona, D. Ariz. No. CV-06-1268-PHX-ROS","cite":"2013 WL 7767705","y":2013,"court":"Sept. 11","by":{"3":"19"}},{"t":"case","label":"GTE Sylvania, Inc. v. Consumers Union of U.S., Inc.","cite":"445 U.S. 375","y":1980,"id":"1979/78-1248","sc":1,"sum":"In connection with an investigation of hazards in the operation of television receivers, respondent Consumer Product Safety Commission (CPSC) obtained various accident reports from television manufacturers, including petitioners. Respondents Consumers Union of the United States, Inc., and Public Citizen's Health Research Group (requesters) sought disclosure of the accident reports under the Freedom of Information …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22","5":"10-11"}},{"t":"case","label":"O’Sullivan v. City of Chicago","cite":"396 F.3d 843","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/396/843/","by":{"3":"22"}},{"t":"case","label":"Roberts v. St. Regis Paper Co.","cite":"653 F.2d 166","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/653/166/","sum":"Holding that retention of jurisdiction clause does not “refer[] to the life of the decree itself”.","sumSrc":"brief:6","by":{"3":"24","5":"15","6":"37"}},{"t":"case","label":"Thompson v. HUD","cite":"404 F.3d 821","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/404/821/","by":{"3":"24","6":"37"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"4":"21"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"4":"17","6":"44"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"22"}},{"t":"case","label":"FTC v. Phoebe Putney Health System, Inc.","cite":"568 U.S. 216","y":2013,"id":"2012/11-1160","sc":1,"sum":"The Court found state-action immunity does not apply if the state's legislature did not clearly articulate intent to allow anticompetitive activity through the Hospital Authorities Act.","sumSrc":"Oyez","by":{"4":"42"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"sum":"The Court found that the Federal Employees' Group Life Insurance Act preempts a Virginia state law regarding beneficiary designation upon divorce.","sumSrc":"Oyez","by":{"4":"18"}},{"t":"case","label":"Home Depot U.S.A., Inc. v. Jackson","cite":"587 U.S. 435","y":2019,"id":"2018/17-1471","sc":1,"sum":"Neither the general removal provision, 28 U. S. C. §1441(a), nor the removal provision in the Class Action Fairness Act of 2005, §1453(b), permit a third-party counterclaim defendant to remove a class-action claim from state to federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"18","5":"45"}},{"t":"case","label":"Kamen v. Kemper Financial Services, Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"19"}},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"sum":"The Court held that the whistleblower-protection section of the Sarbanes-Oxley Act applies to privately-employed individuals.","sumSrc":"Oyez","by":{"4":"32"}},{"t":"case","label":"Majority Forward v. Ben Hill County Board of Elections","cite":"509 F. Supp. 3d 1348","y":2020,"court":"M.D. Ga.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/509/1348/","by":{"4":"17, 40"}},{"t":"case","label":"North Carolina State Conference of NAACP v. Bipartisan Board of Elections & Ethics Enforcement","cite":"2018 WL 3748172","y":2018,"court":"M.D.N.C. Aug. 7","by":{"4":"17"}},{"t":"case","label":"Page(s) Northwest Austin Municipal Utility District Number One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"4":"42"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"4":"41","5":"32"}},{"t":"case","label":"Oncale v. Sundowner Offshore Services, Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"4":"34"}},{"t":"case","label":"Pennsylvania Department of Corrections v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"4":"34"}},{"t":"case","label":"Rivers v. Guerrero","cite":"605 U.S. 443","y":2025,"id":"2024/23-1345","sc":1,"sum":"Once a district court enters its judgment with respect to a first-filed habeas petition, see 28 U. S. C. §2254, a second-in-time filing qualifies as a “second or successive application” under the Antiterrorism and Effective Death Penalty Act of 1996 properly subject to the requirements of §2244(b).","sumSrc":"Holding (supremecourt.gov)","by":{"4":"41"}},{"t":"case","label":"Roberts v. Sea-Land Services, Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"4":"30, 31"}},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"sum":"The Clean Water Act extends only to wetlands that have a continuous surface connection with “waters” of the United States—i.e., with a relatively permanent body of water connected to traditional interstate navigable waters, 33 U. S. C. §1362(7)—making it difficult to determine where the water ends and the wetland begins.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"24"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"4":"31","5":"42"}},{"t":"case","label":"Taylor v. Freeland & Kronz","cite":"503 U.S. 638","y":1992,"id":"1991/91-571","sc":1,"sum":"A trustee may not contest the validity of a claimed exemption after the Rule 4003(b) 30-day period has expired, even though the debtor had no colorable basis for claiming the exemption..","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"41"}},{"t":"case","label":"United Parcel Service, Inc. v. Mitchell","cite":"451 U.S. 56","y":1981,"id":"1980/80-169","sc":1,"sum":"Given the choices present here, and the undesirability of the results of the grievance and arbitral process being suspended in limbo for long periods, the District Court properly chose the 90-day period for the bringing of an action to vacate an arbitration award. Cf. Hines v. Anchor Motor Freight,Inc., 424 U. S. 554. Pp. 60-64..","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"19"}},{"t":"case","label":"United Student Aid Funds, Inc. v. Espinosa","cite":"559 U.S. 260","y":2010,"id":"2009/08-1134","sc":1,"sum":"The Court held that Chapter 13 bankruptcy plans which discharge student loans are not void if the debtor fails to provide evidence of \"undue hardship\" in an adversary proceeding.","sumSrc":"Oyez","by":{"4":"19"}},{"t":"case","label":"Virginia Coalition for Immigrant Rights v. Beals","cite":"2024 WL 4601052","y":2024,"court":"4th Cir. Oct. 27","sum":"Explaining that petitioner’s theory requires reading the distinct terms of “voters” and “registrant” as “having the same meaning”.","sumSrc":"brief:5","by":{"4":"35","5":"41-42","6":"39, 43, 48"}},{"t":"case","label":"Wisconsin Central Limited v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"4":"23"}},{"t":"case","label":"Alabama Coalition for Immigrant Justice v. Allen","cite":"2024 WL 4510476","y":2024,"court":"N.D. Ala. Oct. 16","sum":"Concluding a last-minute “purge list included thousands of United States citizens” who were referred for “criminal investigation”.","sumSrc":"brief:6","by":{"5":"36","6":"48"}},{"t":"case","label":"Amalgamated Sugar Co. v. NL Industries, Inc.","cite":"825 F.2d 634","y":1987,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/825/634/","by":{"5":"16"}},{"t":"case","label":"AT&T Corp. v. Iowa Utilities Board","cite":"525 U.S. 366","y":1999,"id":"1998/97-826","sc":1,"sum":"In a complicated split opinion, the Court held that the FCC has rulemaking authority to uphold those provision of the Act in question. Despite the local nature of some of the LECs involved, the Court emphasized their interconnectivity with regional and national carriers. As such, the FCC could also reach local LEC markets and regulate their competitive business practices.","sumSrc":"Oyez","by":{"5":"21"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"5":"35-36"}},{"t":"case","label":"Binker v. Pennsylvania","cite":"977 F.2d 738","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/977/738/","by":{"5":"12"}},{"t":"case","label":"BLOM Bank SAL v. Honickman","cite":"605 U.S. 204","y":2025,"id":"2024/23-1259","sc":1,"sum":"Relief under Federal Rule of Civil Procedure 60(b)(6) requires extraordinary circumstances, and this standard does not become less demanding when the movant seeks to reopen a case to amend a complaint; a party must first satisfy Rule 60(b) before Rule 15(a)’s liberal amendment standard can apply.","sumSrc":"Holding (supremecourt.gov)","by":{"5":"11"}},{"t":"case","label":"Cinnamon Hills Youth Crisis Center, Inc. v. Saint George City","cite":"685 F.3d 917","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/685/917/","by":{"5":"20","6":"15"}},{"t":"case","label":"Commissioner v. Lundy","cite":"516 U.S. 235","y":1996,"id":"1995/94-1785","sc":1,"sum":"The Court held that in these circumstances a 2-year look-back period applies and the Tax Court lacks jurisdiction to award a refund.","sumSrc":"Oyez","by":{"5":"36"}},{"t":"case","label":"Consumer Advisory Board v. Glover","cite":"989 F.2d 65","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/989/65/","by":{"5":"15"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"5":"15"}},{"t":"case","label":"Dunlop v. Pan American World Airways, Inc.","cite":"672 F.2d 1044","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/672/1044/","by":{"5":"12","6":"33"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"5":"38","6":"43"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"sum":"In 7-2 opinion delivered by Justice Antonin Scalia, the Court held that Gonzalez's Rule 60(b) motion challenged only the district court's previous ruling on the federal statute of limitations. That motion was therefore not the equivalent of a successive habeas petition and could be ruled on by the district court without the 11th Circuit's precertification.","sumSrc":"Oyez","by":{"5":"11"}},{"t":"case","label":"Grace v. Bank Leumi Trust Co.","cite":"443 F.3d 180","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/443/180/","by":{"5":"12"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"5":"22"}},{"t":"case","label":"Kobach v. United States Election Assistance Commission","cite":"576 U.S. 1055","y":2015,"url":"https://supreme.justia.com/cases/federal/us/576/1055/","sc":1,"by":{"5":"4"}},{"t":"case","label":"Kobach v. United States Election Assistance Commission","cite":"772 F.3d 1183","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1183/","sum":"Holding that Kansas and Arizona “failed to meet their evidentiary burden of proving that they cannot enforce their voter qualifications” without DPOC.","sumSrc":"brief:5","by":{"5":"4, 24","6":"2, 6, 13, 23, 25"}},{"t":"case","label":"Mullin v. Doe","cite":"609 U.S. 324","y":2026,"id":"2025/25-1083","sc":1,"sum":"Section 1254a(b)(5)(A) bars judicial review of non-constitutional claims related to Temporary Protected Status (TPS); Miot respondents’ equal protection claim—that Haiti’s TPS designation was terminated because of race—is unlikely to succeed because a race-neutral explanation for the Government’s action exists: the current administration opposes the TPS program as it has been implemented in the past and has terminated every TPS designation that has come up for renewal.","sumSrc":"Holding (supremecourt.gov)","by":{"5":"42"}},{"t":"case","label":"NAACP, Inc. v. Duplin County","cite":"2012 WL 360018","y":2012,"court":"E.D.N.C. Feb. 2","by":{"5":"12"}},{"t":"case","label":"One Love Housing, LLC v. City of Anoka","cite":"93 F.4th 424","y":2024,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/424/","by":{"5":"20"}},{"t":"case","label":"Parents Involved v. Seattle School District","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"sum":"By a 5-4 vote, the Court applied a \"strict scrutiny\" framework and found Jefferson County's enrollment plan unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"5":"30"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"5":"39"}},{"t":"case","label":"Reynolds v. Sims","cite":"377 U.S. 533","y":1964,"id":"1963/23","sc":1,"sum":"The Court held that Alabama's apportionment of the state legislature was unconstitutional under the Equal Protection Clause of the Fourteenth Amendment because representation was not based on population of counties.","sumSrc":"Oyez","by":{"5":"37"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"5":"44"}},{"t":"case","label":"Satsky v. Paramount Communications, Inc.","cite":"7 F.3d 1464","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/7/1464/","by":{"5":"16"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"sum":"To prevail under 42 U. S. C. §12112(a), a plaintiff must plead and prove that she held or desired a job, and could perform its essential functions with or without reasonable accommodation, at the time of an employer’s alleged act of disability-based discrimination; the judgment of the Eleventh Circuit is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"5":"42"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"5":"38"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"5":"26, 35"}},{"t":"case","label":"United States v. Southern Ute Tribe","cite":"402 U.S. 159","y":1971,"id":"1970/515","sc":1,"sum":"Respondent's claims for compensation and accounting are barred by res judicata since they relate to land \"formerly owned or claimed by [the Confederated Bands of Utes] in western Colorado, ceded to [the United States] by the Act of June 15, 1880\" and thus were subject to a final settlement reduced to a consent judgment, to which respondent was a party, made in 1950. Pp. 161-174. 191 Ct. Cl. 1, 423 F. 2d 346, …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"16"}},{"t":"case","label":"United States Student Ass’n Foundation v. Land","cite":"546 F.3d 373","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/546/373/","sum":"Noting that Bell involved an Ohio state law that removed voters “after a hearing on the issue” to “determine[] that a particular challenged individual is not an eligible voter”.","sumSrc":"brief:5","by":{"5":"49"}},{"t":"case","label":"Virginia Coalition for Immigrant Rights v. Beals","cite":"803 F. Supp. 3d 454","y":2025,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/803/454/","by":{"5":"37, 41"}},{"t":"case","label":"Vorchheimer v. Philadelphian Owners Ass’n","cite":"903 F.3d 100","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/903/100/","by":{"5":"20, 27","6":"15, 16"}},{"t":"case","label":"Vote.Org v. Callanen","cite":"89 F.4th 459","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/89/459/","sum":"Holding that states cannot circumvent federal law “by defining all manner of [registration] requirements, . . . as being a qualification to vote”.","sumSrc":"brief:5","by":{"5":"25"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"5":"28"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"5":"28","6":"43"}},{"t":"case","label":"Women’s Elevated Sober Living L.L.C. v. City of Plano","cite":"86 F.4th 1108","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/86/1108/","by":{"5":"20","6":"16"}},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"5":"40"}},{"t":"const","label":"Article I, Section 2, Clause 1","text":"The House of Representatives shall be composed of Members chosen every second Year by the People of the several States, and the Electors in each State shall have the Qualifications requisite for Electors of the most numerous Branch of the State Legislature.","by":{"5":"25"}},{"t":"const","label":"Article I, Section 4, Clause 1","clauses":[["elections-clause","Elections Clause"]],"text":"The Times, Places and Manner of holding Elections for Senators and Representatives, shall be prescribed in each State by the Legislature thereof; but the Congress may at any time by Law make or alter such Regulations, except as to the Places of chusing Senators.","by":{"5":"21"}},{"t":"const","label":"Article I, Section 4, Clause 2","text":"The Congress shall assemble at least once in every Year, and such Meeting shall be on the first Monday in December, unless they shall by Law appoint a different Day.","by":{"5":"17"}},{"t":"usc","label":"8 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/8/1451","by":{"5":"46"}},{"t":"usc","label":"8 U.S.C. § 1481","url":"https://www.law.cornell.edu/uscode/text/8/1481","by":{"5":"46"}},{"t":"reg","label":"11 C.F.R. § 9428.4","url":"https://www.ecfr.gov/current/title-11/section-9428.4","by":{"5":"27"}},{"t":"reg","label":"11 C.F.R. pt. 8","url":"https://www.ecfr.gov/current/title-11/part-8","by":{"5":"24"}},{"t":"case","label":"Boechler, P.C. v. Comm’r","cite":"596 U.S. 199","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/199/","sc":1,"sum":"Noting that parenthetical remarks are “typically used to convey an ‘aside’ or ‘afterthought’” (citation omitted).","sumSrc":"brief:6","by":{"6":"20"}},{"t":"case","label":"Cadillac Fairview/Cal., Inc. v. Dow Chem. Co.","cite":"840 F.2d 691","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/840/691/","by":{"6":"24"}},{"t":"case","label":"Citizens for a Better Env’t v. Gorsuch","cite":"718 F.2d 1117","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/718/1117/","by":{"6":"35"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"6":"14"}},{"t":"case","label":"Cooper v. Aaron","cite":"358 U.S. 1","y":1958,"id":"1957/1_misc","sc":1,"sum":"The Court held that Arkansas officials were bound by federal court orders mandating desegregation.","sumSrc":"Oyez","by":{"6":"34"}},{"t":"case","label":"Dennis v. County of Fairfax","cite":"55 F.3d 151","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/55/151/","sum":"Noting that parties to a consent decree “generally admit nothing in the way of guilt”.","sumSrc":"brief:6","by":{"6":"36"}},{"t":"case","label":"Dep’t of Homeland Sec. v. League of Women Voters","cite":"2026 WL 2879700","y":2026,"court":"U.S. Sep. 25","by":{"6":"51"}},{"t":"case","label":"Deposit Bank of Frankfort v. Bd. of Councilmen","cite":"191 U.S. 499","y":1903,"id":"scdb/1903-006","sc":1,"sum":"A right claimed under the Federal Constitution, finally adjudicated in the Federal courts, can never be taken away or impaired by state decisions, refusing to give due weight to such Federal judgment properly invoked for the protection of the party in whose favor it' was rendered.","sumSrc":"Headnote (U.S. Reports)","by":{"6":"34, 37"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"6":"21"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"21"}},{"t":"case","label":"Food & Drug Admin. v. R. J. Reynolds Vapor Co.","cite":"606 U.S. 226","y":2025,"id":"2024/23-1187","sc":1,"sum":"Retailers who would sell a new tobacco product if not for the FDA’s denial order may seek judicial review of that order under 21 U. S. C. §387l(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"6":"38"}},{"t":"case","label":"Gonzales & Gonzales Bonds & Ins. Agency, Inc. v. Dep’t of Homeland Sec.","cite":"107 F.4th 1064","y":2024,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/107/1064/","sum":"Holding that “[i]n 1998,” the “pertinent definition of the adverb ‘only’” was “solely, exclusively”.","sumSrc":"brief:6","by":{"6":"18"}},{"t":"case","label":"GTE Serv. Corp. v. FCC","cite":"205 F.3d 416","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/205/416/","by":{"6":"16"}},{"t":"case","label":"Hook v. Ariz. Dep’t of Corrs.","cite":"107 F.3d 1397","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/107/1397/","sum":"Holding that it is “consistent with the Supremacy Clause” that a consent decree vindicating federal rights “preclude[s] the application of” a state statute enacted to defeat the decree.","sumSrc":"brief:6","by":{"6":"35"}},{"t":"case","label":"Hook v. Ariz. Dep’t of Corrs.","cite":"972 F.2d 1012","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/972/1012/","by":{"6":"32"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"6":"19"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"6":"20"}},{"t":"case","label":"Lackey v. Stinnie","cite":"604 U.S. 192","y":2025,"id":"2024/23-621","sc":1,"sum":"Plaintiffs who gained only preliminary injunctive relief before this action became moot do not qualify as “prevailing part[ies]” eligible for attorney’s fees under 42 U. S. C. §1988(b) because no court conclusively resolved their claims by granting enduring relief on the merits that altered the legal relationship between the parties.","sumSrc":"Holding (supremecourt.gov)","by":{"6":"32"}},{"t":"case","label":"LULAC v. Exec. Off. of the President","cite":"818 F. Supp. 3d 34","y":2026,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/818/34/","by":{"6":"28"}},{"t":"case","label":"McNutt v. Dep’t of Just.","cite":"173 F.4th 204","y":2026,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/173/204/","sum":"Recognizing “necessary” historically meant “indispensably requisite” but receives unique construction in the Necessary and Proper Clause.","sumSrc":"brief:6","by":{"6":"17"}},{"t":"case","label":"Milk Wagon Drivers Union v. Meadowmoor Dairies","cite":"312 U.S. 287","y":1941,"id":"scdb/1940-089","sc":1,"sum":"that it is not for this Court to make an independent valuation of the testimony before the master or to substitute its judgment for that of the state court resolving conflicts in the testimony or its interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"32"}},{"t":"case","label":"N.Y. State Ass’n for Retarded Child. Inc. v. Carey","cite":"706 F.2d 956","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/706/956/","by":{"6":"32"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"6":"42"}},{"t":"case","label":"Reynolds v. Roberts","cite":"202 F.3d 1303","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/202/1303/","by":{"6":"36"}},{"t":"case","label":"Riverdale Cotton Mills v. Ala. & Ga. Mfg. Co.","cite":"198 U.S. 188","y":1905,"id":"scdb/1904-081","sc":1,"sum":"A Federal court exercising a jurisdiction apparently belonging to it, may thereafter, by ancillary suit, inquire whether that jurisdiction in fact existed, and may protect the title which it has decreed as against all parties to the original suit and prevent any of such parties from relitigatr ing' questions of right already determined.","sumSrc":"Headnote (U.S. Reports)","by":{"6":"34"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"3"}},{"t":"case","label":"Stoll v. Gottlieb","cite":"305 U.S. 165","y":1938,"id":"scdb/1938-006","sc":1,"sum":"1. A contention that a ruling of a state supreme court disregarded decrees of a court of the United States, raised a federal question reviewable under § 237b of the Judicial Code.","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"34"}},{"t":"case","label":"Studiengesellschaft Kohle mbH v. Eastman Kodak Co.","cite":"713 F.2d 128","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/713/128/","by":{"6":"24"}},{"t":"case","label":"Swift & Co. v. United States","cite":"276 U.S. 311","y":1928,"id":"scdb/1927-141","sc":1,"sum":"1. Where a consent decree, entered in a suit brought by the Government under the Anti-Trust Act, provided for entertaining at any time thereafter any application which the parties might make in respect to it, motions to vacate it made by defendants four years later in response to petitions of intervention and entitled in the suit, were part of the original cause.","sumSrc":"Headnote (U.S. Reports)","by":{"6":"36"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"6":"15"}},{"t":"case","label":"Teamsters Loc. 177 v. United Parcel Serv.","cite":"966 F.3d 245","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/966/245/","by":{"6":"35"}},{"t":"case","label":"Tex. League of United Latin Am. Citizens v. Whitley","cite":"2019 WL 7938511","y":2019,"court":"W.D. Tex. Feb. 27","by":{"6":"48"}},{"t":"case","label":"Texas v. EPA","cite":"983 F.3d 826","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/983/826/","by":{"6":"18"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"sum":"The Court held that the Cage rule was not \"made retroactive to cases on collateral review by the Supreme Court.\" Justice Thomas wrote for the Court that \"[b]ecause 'made' means 'held'...it is clear that the Cage rule has not been 'made retroactive to cases on collateral review by the Supreme Court.' Cage itself does not hold that it is retroactive.","sumSrc":"Oyez","by":{"6":"20"}},{"t":"case","label":"United States v. Armour & Co.","cite":"402 U.S. 673","y":1971,"id":"1970/759","sc":1,"sum":"The ownership of the majority of the stock of Armour & Co., a meatpacker, by Greyhound Corp., which has retail food subsidiaries and accordingly engages in business that may be forbidden to Armour by the Meat Packers Consent Decree of 1920, in itself and without any evidentiary showing as to the consequences, does not violate the Decree's prohibition against Armour's \"directly or indirectly... engaging in or …","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"37"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"6":"43"}},{"t":"case","label":"United States v. Nelson-Rodriguez","cite":"319 F.3d 12","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/319/12/","by":{"6":"24"}},{"t":"case","label":"United States v. Therve","cite":"764 F.3d 1293","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/764/1293/","by":{"6":"24"}},{"t":"case","label":"Wachovia Bank v. Schmidt","cite":"546 U.S. 303","y":2006,"id":"2005/04-1186","sc":1,"sum":"The Court ruled that a national bank is \"located\" in, and therefore a \"citizen\" of, only the state in which its main office is located. Looking to the history of Congress's diversity jurisdiction statutes, the Court concluded that the word \"located\" need not be interpreted to mean any state where a bank has a physical presence.","sumSrc":"Oyez","by":{"6":"21"}},{"t":"usc","label":"52 U.S.C. § 10502","url":"https://www.law.cornell.edu/uscode/text/52/10502","by":{"6":"47"}},{"t":"usc","label":"52 U.S.C. § 21083","url":"https://www.law.cornell.edu/uscode/text/52/21083","by":{"6":"28"}}]};